INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '図形の組み合わせ', '図のような合同な直角二等辺三角形が3個ある。これらをすべて使ってある図形を作ったとき、あり得ない図形は次のうちどれか。', NULL, '["台形","平行四辺形","正五角形","凧形","二等辺三角形"]', 2, '["直角二等辺三角形の内角は45°、45°、90°です。ピースを組み合わせて作った図形のどの頂点の角も、45°と90°の角をいくつか足し合わせた大きさになるため、必ず45°の倍数になります。\n選択肢のうち、正五角形の内角は108°であり、45°の倍数ではないため、45°と90°の組み合わせでは作ることができません。\nよって、正解は3・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '図形の組み合わせ', '図のような合同な直角二等辺三角形が4個ある。これらをすべて使ってある図形を作ったとき、あり得ない図形は次のうちどれか。', NULL, '["長方形","ひし形（内角60°・120°のもの）","台形","平行四辺形","凧形"]', 1, '["問題1と同様に、できあがる図形のすべての内角は45°の倍数になります。\n選択肢2の「内角60°・120°のひし形」は、60°・120°がいずれも45°の倍数ではないため作ることができません。\n（長方形・台形・平行四辺形・凧形はいずれも90°・45°・135°の組み合わせで作ることができます。）\nよって、正解は2・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '図形の組み合わせ', '図のような合同な直角二等辺三角形が5個ある。これらをすべて使ってある図形を作ったとき、あり得ない図形は次のうちどれか。', NULL, '["正六角形","台形","長方形","平行四辺形","凧形"]', 0, '["同様の考え方で、できあがる図形の内角は必ず45°の倍数になります。\n正六角形の内角は120°であり、45°の倍数ではないため作ることができません。\nよって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAxMjAgOTAiIHdpZHRoPSIxNDAiIGhlaWdodD0iMTA1Ij4KPHBvbHlnb24gcG9pbnRzPSIxMCw4MCA5MCw4MCA5MCwxMCIgZmlsbD0iI2RiZTlmNyIgc3Ryb2tlPSIjMmI1ZjllIiBzdHJva2Utd2lkdGg9IjIiLz4KPC9zdmc+');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '図形の組み合わせ', '図のような合同な直角二等辺三角形が6個ある。これらをすべて使ってある図形を作ったとき、あり得ない図形は次のうちどれか。', NULL, '["正三角形","長方形","平行四辺形","台形","六角形（内角がすべて90°または135°のもの）"]', 0, '["できあがる図形の内角は必ず45°の倍数になります。\n正三角形の内角は60°であり、45°の倍数ではないため作ることができません。\nよって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAxMjAgOTAiIHdpZHRoPSIxNDAiIGhlaWdodD0iMTA1Ij4KPHBvbHlnb24gcG9pbnRzPSIxMCw4MCA5MCw4MCA5MCwxMCIgZmlsbD0iI2RiZTlmNyIgc3Ryb2tlPSIjMmI1ZjllIiBzdHJva2Utd2lkdGg9IjIiLz4KPC9zdmc+');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '塗り分け', '以下のような図形のA、B、C、Dの領域を赤、青、黄、緑、紫、白の6色を使って塗り分けたい。ただし、隣り合う領域は異なる色で塗り分けるものとする。このとき、塗り分け方は何通りあるか。ただし、使わない色があってもよいものとする。', NULL, '["480通り","625通り","750通り","900通り","1080通り"]', 2, '["A、B、C、Dは一列に並んでおり、隣り合う領域（A-B、B-C、C-D）のみが接しています（AとC、AとD、BとDは接していません）。\nAは6色から自由に選べるので6通り。Bは Aと異なればよいので5通り。Cは Bと異なればよいので5通り。Dは Cと異なればよいので5通りです。\nよって、6×5×5×5＝750通り。\nよって、正解は3・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '塗り分け', '以下のような2×2に区切られた図形のA、B、C、Dの領域を赤、青、黄、緑、紫、白の6色を使って塗り分けたい。ただし、辺を共有する（角のみで接する場合は除く）領域は異なる色で塗り分けるものとする。このとき、塗り分け方は何通りあるか。ただし、使わない色があってもよいものとする。', NULL, '["480通り","630通り","720通り","750通り","900通り"]', 1, '["A-B、B-C、C-D、D-Aがそれぞれ辺を共有しており（AとC、BとDは角のみで接し隣り合わない）、4つの領域が輪のようにつながった構造（4-サイクル）です。\nこのような輪状の塗り分けの総数は、色数をkとすると (k－1)^4＋(k－1) で求められます。\nk＝6を代入すると、5^4＋5＝625＋5＝630通り。\nよって、正解は2・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '塗り分け', '以下のような十字形の図形のO、A、B、C、Dの領域を赤、青、黄、緑、紫、白の6色を使って塗り分けたい。ただし、辺を共有する領域は異なる色で塗り分けるものとする（A、B、C、Dは互いに角でしか接しておらず、隣り合っていない）。このとき、塗り分け方は何通りあるか。ただし、使わない色があってもよいものとする。', NULL, '["2500通り","3000通り","3750通り","4500通り","5000通り"]', 2, '["中央のOはA、B、C、Dすべてと隣り合いますが、A、B、C、D同士は角でしか接していないため互いに異なる色にする必要はありません。\nOの塗り方は6通り。A、B、C、Dはそれぞれ「Oと異なる色」であればよいので、各5通り。\nよって、6×5×5×5×5＝6×625＝3750通り。\nよって、正解は3・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '塗り分け', '以下のような図形のA、B、C、D、Eの領域を赤、青、黄、緑、紫、白の6色を使って塗り分けたい。ただし、隣り合う領域は異なる色で塗り分けるものとする。図の中心でA、B、Cの3領域は互いにすべて隣り合っており、DはAのみと、EはCのみと隣り合っている。このとき、塗り分け方は何通りあるか。ただし、使わない色があってもよいものとする。', NULL, '["1800通り","2400通り","3000通り","3600通り","4200通り"]', 2, '["まずA、B、Cを塗ります。3領域は互いにすべて隣り合っているため、Aは6通り、Bは残り5通り、Cは残り4通りで、6×5×4＝120通り。\nDは A のみと隣り合うので、Aと異なればよく5通り。Eは Cのみと隣り合うので、Cと異なればよく5通り。\nよって、120×5×5＝3000通り。\nよって、正解は3・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '敷き詰めパズル', '以下の図は、1辺の長さが1の正方形3個を組み合わせて作ったL字型の図形である。この図形を隙間なく敷き詰めて、できるだけ小さい正方形を作るには、この図形は最低何枚必要か。', NULL, '["6枚","8枚","10枚","12枚","16枚"]', 3, '["このL字型（L字トロミノ）を2枚使うと、互いに180°回転させて組み合わせることで、縦2×横3の長方形を作ることができます。\n次に、この2×3の長方形を並べて正方形を作ることを考えます。2と3の最小公倍数は6なので、縦方向に3枚（2×3＝6）、横方向に2枚（3×2＝6）並べると、1辺の長さが6の正方形ができます。\nこのとき使用する2×3長方形の枚数は3×2＝6枚。1つの長方形はL字型2枚からできているので、必要なL字型の枚数は 6×2＝12枚 です。\nよって、正解は4・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '敷き詰めパズル', '以下の図は、1辺の長さが1の正方形4個を組み合わせて作ったT字型の図形である。この図形を隙間なく敷き詰めて、できるだけ小さい正方形を作るには、この図形は最低何枚必要か。', NULL, '["2枚","4枚","6枚","8枚","16枚"]', 1, '["このT字型（T字テトロミノ）は、4枚を風車状に組み合わせることで、直接1辺の長さが4の正方形を作ることができる、よく知られた図形です（面積4×4＝16＝4枚×4マスと一致）。\nこれより小さい正方形（1辺1～3）はマス目の数が足りず作れないため、最低枚数は4枚となります。\nよって、正解は2・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '敷き詰めパズル', '辺の長さが2、3の長方形を隙間なく敷き詰めて、できるだけ小さい正方形を作りたい。この長方形は最低何枚必要か。', NULL, '["4枚","6枚","9枚","12枚","15枚"]', 1, '["2と3の最小公倍数は6なので、1辺の長さが6の正方形を目標にします。\n縦方向には 6÷2＝3枚、横方向には 6÷3＝2枚並べればよいので、必要な枚数は 3×2＝6枚 です。\nよって、正解は2・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '敷き詰めパズル', '辺の長さが3、5の長方形を隙間なく敷き詰めて、できるだけ小さい正方形を作りたい。この長方形は最低何枚必要か。', NULL, '["8枚","10枚","12枚","15枚","18枚"]', 3, '["3と5の最小公倍数は15なので、1辺の長さが15の正方形を目標にします。\n縦方向には 15÷3＝5枚、横方向には 15÷5＝3枚並べればよいので、必要な枚数は 5×3＝15枚 です。\nよって、正解は4・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '正八面体の展開図', '以下の5つの展開図のうち、正八面体の展開図として正しいものはどれか。', NULL, '["1","2","3","4","5"]', 2, '["1は三角形が7枚しかなく面の数（8枚）が不足しているため誤りです。\n2は8枚の三角形がまっすぐ一列に並んだ帯状の展開図ですが、このまま折っても8つの面が正しく閉じた正八面体にならないため誤りです（帯を輪にする「継ぎ目」の三角形が存在しません）。\n4は4枚ずつの2つのグループに分かれてしまっており、1枚の展開図としてつながっていないため誤りです。\n5は上に張り出した三角形2枚が隣り合う位置にあり、実際に組み立てると面同士が重なってしまうため誤りです。\n3は6枚の帯の両端から離れた位置（互いに反対側寄り）に1枚ずつ三角形を配置した形になっており、正しく組み立てると正八面体が完成します。\nよって、正解は3・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '正八面体の展開図', '以下の5つの展開図のうち、正八面体の展開図として正しいものはどれか。', NULL, '["1","2","3","4","5"]', 0, '["2はまっすぐ一列の帯状の展開図で、正八面体にはならないため誤りです。\n3は三角形が7枚しかなく、枚数が不足しているため誤りです。\n4は4枚ずつ2つに分かれてしまい、1枚の展開図としてつながっていないため誤りです。\n5は下に張り出す三角形2枚が隣り合う位置にあり、組み立てると面が重なってしまうため誤りです。\n1は帯の下側と上側、互いに離れた位置に1枚ずつ三角形を配置しており、正しく正八面体に組み立てることができます。\nよって、正解は1・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '正八面体の展開図', '以下の5つの展開図のうち、正八面体の展開図として正しいものはどれか。', NULL, '["1","2","3","4","5"]', 4, '["1は三角形が7枚しかなく不足しているため誤りです。\n2は2つのグループに分かれてつながっていないため誤りです。\n3は上に張り出す三角形2枚が隣り合っており、組み立てると重なってしまうため誤りです。\n4はまっすぐ一列の帯状の展開図であり、正八面体にはならないため誤りです。\n5は帯の上側と下側、互いに離れた位置に1枚ずつ配置されており、正しく正八面体に組み立てることができます。\nよって、正解は5・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '正八面体の展開図', '以下の5つの展開図のうち、正八面体の展開図として正しいものはどれか。', NULL, '["1","2","3","4","5"]', 1, '["1は三角形が7枚しかなく不足しているため誤りです。\n3は2つのグループに分かれてつながっていないため誤りです。\n4はまっすぐ一列の帯状で、正八面体にはならないため誤りです。\n5は張り出す三角形が帯の端に近すぎる位置にあり、組み立てると面が重なってしまうため誤りです。\n2は7枚の帯のちょうど中央付近に1枚だけ三角形を配置した形で、正しく正八面体に組み立てることができます。\nよって、正解は2・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '正八面体の展開図', '以下の5つの展開図のうち、正八面体の展開図として正しいものはどれか。', NULL, '["1","2","3","4","5"]', 3, '["1は三角形が7枚しかなく不足しているため誤りです。\n2はまっすぐ一列の帯状で、正八面体にはならないため誤りです。\n3は張り出す三角形3枚が帯の一方の端付近に集中しており、組み立てると面が重なってしまうため誤りです。\n5は2つのグループに分かれてつながっていないため誤りです。\n4は5枚の帯の下側に、間隔をあけて3枚の三角形を均等に配置した形になっており、正しく正八面体に組み立てることができます。\nよって、正解は4・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '立方体の展開図', '以下5つの展開図のうち、立方体（正六面体）の展開図として正しいものはどれか。', NULL, '["1","2","3","4","5"]', 2, '["1はまっすぐ一列に6マスが並んだ形で、立方体には組み立てられません（帯を丸めても上下のふたが用意できません）。\n2は2×3の長方形ブロックで、そのまま折っても立方体にはなりません。\n4は4マスと2マスの2グループに分かれてつながっていないため誤りです。\n5は上下2段をずらして並べたS字型で、立方体には組み立てられません。\n3は4マスの列の中央のマスの上下にそれぞれ1マスずつ張り出した「十字形」で、これは立方体の展開図として非常によく知られた正しい形です。\nよって、正解は3・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '一筆書き', '以下の5つの図形のうち、一筆書き（同じ線を二度なぞらず、ペンを紙から離さずに描くこと）ができないものはどれか。', NULL, '["1","2","3","4","5"]', 4, '["一筆書きができるのは、奇数本の線が集まる頂点（奇点）の数が「0個」または「2個」の図形に限られます。\n1（中線付き三角形）：頂点は上・左下・右下・中線の下端の4つ。奇点は2つ→描ける。\n2（8の字）：すべての頂点で偶数本の線が交わる→描ける。\n3（対角線付きの家形）：奇点は2つ→描ける。\n4（対角線なしの家形）：奇点は2つ→描ける。\n5（正方形＋対角線2本）：対角線の交点も頂点とみなすと、正方形の4つの頂点はすべて奇点（3本の線が集まる）となり、奇点の数が4個になるため、一筆書きはできません。\nよって、正解は5・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri) VALUES ('tgweb_traditional_math', '図形問題', '図形の回転・裏返し', '以下の5つの図形のうち、1つだけ他の4つを回転させても作ることができないもの（裏返さないと作れないもの）がある。それはどれか。', NULL, '["1","2","3","4","5"]', 4, '["基準の図形（1）は「棒3マス＋旗1マス」の形で、旗は棒の下端から見て右側についています。この図形を90°・180°・270°回転させると、それぞれ2、3、4のようになり、いずれも棒の「進行方向に対して右側」に旗がついた形になっています。\n5は棒が縦向きで、旗が棒の上端の左側についています。これは1～4のどの回転とも一致せず、1を裏返し（鏡映）にした形になっています。\nよって、正解は5・・・（答）となります。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB従来型非言語: 図形問題）', 'data:image/svg+xml;base64,');
